import { emitPageLink } from "../pageLink.js";
import { parseArgs } from "../parseArgs.js";
import { buildExperimentsPathForDataset } from "./openExperiments.js";
const ARGS = [
    {
        name: "datasetId",
        format: "uuid",
        description: "Dataset whose experiments to display.",
    },
];
const FLAGS = [
    {
        name: "show-tokens",
        boolean: true,
        description: "Show token-usage columns in the experiments view.",
    },
];
export async function runOpenDatasetExperiments(_platform) {
    const { positional, flags } = parseArgs({
        positional: ARGS,
        flags: FLAGS,
        description: "Print a link to a dataset's experiments and exit.",
    });
    emitPageLink(buildExperimentsPathForDataset(positional[0], {
        showTokens: flags["show-tokens"] === true,
    }));
}
